// Official multi-system Query facts; UTF16 anchor check: 😀.
@component export class Position {x:f32=0;y:f32=0;}
@component export class Velocity {x:f32=0;}
@system export function readPosition(q:Query<[Read<Position>]>):void {}
@system export function readPosition2(q:Query<[Read<Position>]>):void {}
@system export function writePositionX(q:Query<[Write<Position>]>,dt:f32):void {
 for(const [p] of q){p.x += dt;}
}
@system export function writePositionY(q:Query<[Write<Position>]>,dt:f32):void {
 for(const [p] of q){p.y += dt;}
}
@system export function writeVelocity(q:Query<[Write<Velocity>]>,dt:f32):void {
 for(const [v] of q){v.x += dt;}
}
@system export function copyPositionToVelocity(q:Query<[Read<Position>,Write<Velocity>]>,dt:f32):void {
 for(const [p,v] of q){v.x = p.x * dt;}
}
@system export function aliasPosition(q:Query<[Write<Position>,Read<Position>]>,dt:f32):void {
 for(const [p,r] of q){p.x += r.y * dt;}
}

